import React, { useState, useEffect } from "react";
import "bootstrap/dist/css/bootstrap.min.css";
import { useParams, useNavigate } from "react-router-dom";
import private_api from "../../server/private_api";

const Avaliacao = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [avaliacoes, setAvaliacoes] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [curso, setCurso] = useState(null);

  useEffect(() => {
    const fetchAvaliacoes = async () => {
      try {
        setLoading(true);
        setError(null);

        // Primeiro obtemos os dados do aluno e seu curso
        const alunoResponse = await private_api.get(`/aluno/${id}`);
        const aluno = alunoResponse.data;

        if (!aluno || !aluno.curso) {
          setError("Aluno ou curso não encontrado");
          return;
        }

        setCurso(aluno.curso);

        // Depois obtemos as avaliações do curso do aluno
        const avaliacoesResponse = await private_api.get(
          `/aluno/${id}/avaliacoes`
        );
        const avaliacoesData = avaliacoesResponse.data || [];

        // Processamos as avaliações para separar disponíveis e submetidas
        const processadas = avaliacoesData.map((avaliacao) => {
          const submetida =
            avaliacao.submissoes && avaliacao.submissoes.length > 0;
          return {
            ...avaliacao,
            submetida,
            submissao: submetida ? avaliacao.submissoes[0] : null,
          };
        });

        setAvaliacoes(processadas);
      } catch (err) {
        console.error("Erro ao carregar avaliações:", err);
        setError(
          err.response?.data?.error || "Não foi possível carregar as avaliações"
        );
      } finally {
        setLoading(false);
      }
    };

    fetchAvaliacoes();
  }, [id]);

  const handleRealizarAvaliacao = (avaliacaoId) => {
    navigate(`/realizar-avaliacao/${avaliacaoId}`);
  };

  if (loading) {
    return (
      <div className="d-flex justify-content-center mt-5">
        <div className="spinner-border text-primary" role="status">
          <span className="visually-hidden">Carregando...</span>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="container mt-5">
        <div className="alert alert-danger text-center">
          {error}
          <button
            className="btn btn-link"
            onClick={() => window.location.reload()}
          >
            Tentar novamente
          </button>
        </div>
      </div>
    );
  }

  // Filtra avaliações disponíveis (não submetidas)
  const avaliacoesDisponiveis = avaliacoes.filter((a) => !a.submetida);
  // Filtra avaliações já submetidas
  const avaliacoesSubmetidas = avaliacoes.filter((a) => a.submetida);

  return (
    <div
      className="container-fluid d-flex flex-column align-items-center"
      style={{
        backgroundColor: "#E7EFF4",
        minHeight: "100vh",
        padding: "20px",
      }}
    >
      <nav className="nav nav-tabs mb-3 bg-white p-2 w-75 d-flex justify-content-center">
        <a className="nav-link" href={`/alunocursos/${id}`}>
          Cursos
        </a>
        <a className="nav-link" href={`/alunoaulas/${id}`}>
          Aulas
        </a>
        <a className="nav-link active" href={`/alunoavaliacao/${id}`}>
          Avaliações
        </a>
      </nav>

      <h2 className="mb-3 text-center">Avaliações</h2>

      {curso && (
        <div className="alert alert-info w-75 mb-4">
          Curso atual: <strong>{curso.nome}</strong> (Nível: {curso.nivel})
        </div>
      )}

      {/* Avaliações disponíveis */}
      <div className="bg-white p-3 rounded shadow w-75 mb-4">
        <h4>Faça uma avaliação</h4>
        {avaliacoesDisponiveis.length > 0 ? (
          <div>
            <p>Selecione uma avaliação para realizar:</p>
            <div className="list-group">
              {avaliacoesDisponiveis.map((avaliacao) => (
                <div
                  key={avaliacao.id}
                  className="list-group-item d-flex justify-content-between align-items-center"
                >
                  <div>
                    <h5>{avaliacao.titulo}</h5>
                    <p className="mb-1">{avaliacao.descricao}</p>
                    <small className="text-muted">
                      Criada por:{" "}
                      {avaliacao.professor?.utilizador?.nome || "Professor"} |
                      Pontuação máxima: {avaliacao.pontuacaoMaxima} | Prazo:{" "}
                      {new Date(avaliacao.dataFim).toLocaleString()}
                    </small>
                  </div>
                  <button
                    className="btn btn-primary"
                    onClick={() => handleRealizarAvaliacao(avaliacao.id)}
                  >
                    Realizar
                  </button>
                </div>
              ))}
            </div>
          </div>
        ) : (
          <div className="alert alert-success">
            Parabéns! Você completou todas as avaliações disponíveis.
          </div>
        )}
      </div>

      {/* Avaliações submetidas */}
      <div className="bg-white p-3 rounded shadow w-75">
        <h4>Suas submissões</h4>
        {avaliacoesSubmetidas.length > 0 ? (
          <div className="table-responsive">
            <table className="table table-hover">
              <thead className="table-light">
                <tr>
                  <th>Avaliação</th>
                  <th>Professor</th>
                  <th>Pontuação</th>
                  <th>Tempo</th>
                  <th>Submetida em</th>
                </tr>
              </thead>
              <tbody>
                {avaliacoesSubmetidas.map((avaliacao) => (
                  <tr key={avaliacao.id}>
                    <td>
                      <strong>{avaliacao.titulo}</strong>
                      <div className="text-muted small">
                        {avaliacao.descricao}
                      </div>
                    </td>
                    <td>
                      {avaliacao.professor?.utilizador?.nome || "Professor"}
                    </td>
                    <td>
                      <span
                        className={`badge ${
                          avaliacao.submissao.pontuacao >=
                          avaliacao.pontuacaoMaxima * 0.5
                            ? "bg-success"
                            : "bg-warning"
                        }`}
                      >
                        {avaliacao.submissao.pontuacao}/
                        {avaliacao.pontuacaoMaxima}
                      </span>
                    </td>
                    <td>{avaliacao.submissao.tempo || "--:--"}</td>
                    <td>
                      {new Date(
                        avaliacao.submissao.dataSubmissao
                      ).toLocaleString()}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        ) : (
          <div className="alert alert-info">
            Você ainda não completou nenhuma avaliação.
          </div>
        )}
      </div>
    </div>
  );
};

export default Avaliacao;
